#!/usr/bin/env bash
set -u
ROOT="$(cd "$(dirname "$0")" && pwd)"; DB="${DB_PATH:-$ROOT/data/filestorage.db}"; BACKUPS="$ROOT/backups"; mkdir -p "$(dirname "$DB")" "$BACKUPS"
tool(){ (cd "$ROOT" && mvn -q -DskipTests package >/dev/null && mvn -q dependency:build-classpath -Dmdep.outputFile=/tmp/avidrive-cp >/dev/null && DB_PATH="$DB" java -cp "target/classes:$(cat /tmp/avidrive-cp)" com.avizero.avidrive.tool.DbTool "$@"); }
confirm(){ read -r -p "Type $1 to confirm: " x; [ "$x" = "$1" ]; }
while true; do echo "1 Start 2 Stop 3 Frontend 4 Stop frontend 5 Status 6 Reset 7 Quota 8 Backup 9 Backups 10 Restore 11 Hash 12 Verify 13 SQL 14 Init 15 Exit"; read -r -p "> " n; case "$n" in
1) (cd "$ROOT"&&mvn -q spring-boot:run>backend.log 2>&1&echo $!>mode_pids_bec.txt);;2) kill "$(cat mode_pids_bec.txt 2>/dev/null)" 2>/dev/null||true;;3)(cd "$ROOT/frontend"&&npm run dev>../frontend.log 2>&1&echo $!>../mode_pids_front.txt);;4)kill "$(cat mode_pids_front.txt 2>/dev/null)" 2>/dev/null||true;;5)ps -p "$(cat mode_pids_bec.txt 2>/dev/null)" 2>/dev/null||echo stopped;;6)confirm RESET&&confirm "RESET DATABASE"&&rm -f "$DB"&&rm -rf "$ROOT/storage";;7)tool run-sql "UPDATE users SET used_bytes=0;";;8)cp -f "$DB" "$BACKUPS/filestorage-$(date +%Y%m%d-%H%M%S).db";;9)ls -1 "$BACKUPS";;10)read -r -p "Backup: " f;confirm RESTORE&&cp "$BACKUPS/$f" "$DB";;11)read -r -s -p "Password: " p;echo;tool hash-password "$p";;12)read -r -s -p "Password: " p;echo;read -r -p "Hash: " h;tool verify-password "$p" "$h";;13)read -r -p "SQL: " q;tool run-sql "$q";;14)tool run-sql "SELECT 1;";;15)exit 0;;esac;done
